import {escapeHtml as esc} from './agent-view.js';
import {LIVE_STATUSES} from './runtime-client.js';
import {runProgressView} from './progress-view.js';
import {warmupView} from './warmup-view.js';
const metric=v=>v?`${v.passed} / ${v.total}`:'尚未評測';
export function repairView(runtime){
 const workspace=runtime.data?.repair,run=runtime.selectedRepairRun||workspace?.latestRun,result=run?.repairResult;
 const active=['queued','running'].includes(runtime.data?.latestRun?.status),stale=!!runtime.error||!runtime.capabilities||!workspace;
 const sdk=workspace?.sdk,disabled=stale||runtime.actionBusy||active||runtime.data?.provider?.busy||!sdk?.available;
 const discovering=sdk?.errorCode==='not_probed';
 const evidence=runtime.repairEvidence?.runId===run?.id?runtime.repairEvidence:null;
 return `<div class="page-heading"><div><p class="eyebrow">NANOBOT SDK · PYTHON REPAIR</p><h1>Python 修復實驗</h1><p>一個真實 nanobot Worker、固定 Skill 與受控工具；獨立測試決定修復結果。</p></div><div class="actions"><button class="button secondary" data-live-refresh>↻ 更新狀態</button><button class="button primary" data-repair-start ${disabled?'disabled':''}>開始 Python 修復</button>${run&&['queued','running'].includes(run.status)?`<button class="button danger" data-live-cancel="${esc(run.id)}">取消這輪</button>`:''}</div></div>
 <div class="demo-banner"><span class="info-icon">i</span><div><strong>nanobot 0.3.5 SDK · 受控 Python fixture</strong><span>只開放 read_solution、write_solution、run_tests。只改 solution.py；不執行任意 shell、不修改專案原始碼。此頁 Skill 固定；可在 GEPA 技能最佳化頁進行搜尋。</span></div><a href="#logs">檢閱模組 Log ↗</a></div>
 ${stale?`<div class="error-banner spaced">${esc(runtime.error||'等待 WSL 本機服務')}。請使用 localhost GUI。</div>`:''}
 <section class="card spaced execution-progress"><h2>SDK 與執行設定</h2><p class="body-copy">SDK：${sdk?.available?`已可用 · ${esc(sdk.version)}`:discovering?'偵測中，請稍候':'尚未可用'}${sdk?.error&&!discovering?` · ${esc(sdk.error)}`:''}<br>若偵測完成後仍不可用，請停止 GUI，在 WSL 專案執行 <code>bash scripts/install-nanobot.sh</code>，再啟動 GUI。SDK 安裝在獨立的 .venv-nanobot，不更改原有模型設定。</p><div class="actions card-actions"><label>模型呼叫上限<input data-repair-budget type="number" min="2" max="12" value="${runtime.repairBudget??8}" ${active?'disabled':''}></label><label>整輪上限（秒）<input data-repair-seconds type="number" min="60" max="7200" value="${runtime.repairSeconds??900}" ${active?'disabled':''}></label><label>單次模型上限（秒）<input data-repair-call-seconds type="number" min="10" max="3600" value="${runtime.repairCallSeconds??120}" ${active?'disabled':''}></label><button class="button secondary" data-live-toggle>${runtime.enabled?'暫停 polling':'繼續 polling'}</button></div><p class="body-copy">工具最多 24 次。每輪使用全新工作目錄／session；模型、Skill、工具與預算在提交時凍結。請先暖機，並在框架整合設定足夠的輸出 tokens。</p></section>
 ${warmupView(runtime.data?.provider,{disabled:!!active||runtime.actionBusy,stale:stale||runtime.enabled===false})}
 ${runProgressView(runtime,run)}
 <div class="metrics spaced"><article class="metric"><div>修復前 · 公開測試</div><strong>${metric(result?.baseline.visible)}</strong></article><article class="metric"><div>修復後 · 公開測試</div><strong>${metric(result?.candidate.visible)}</strong></article><article class="metric"><div>修復後 · 最終測試</div><strong>${metric(result?.candidate.hidden)}</strong></article><article class="metric"><div>可信結果</div><strong class="runtime-metric">${result?(result.repairPassed?'修復通過':'修復未通過'):run?LIVE_STATUSES[run.status]:'尚未開始'}</strong><small>12 個固定 cases；不代表其他 Python 任務</small></article></div>
 <section class="card spaced"><div class="card-heading"><div><h2>修復與工具證據</h2><p>最終測試在 SDK 工作完成、修復檔凍結後執行；模型的文字聲明不計分。</p></div><button class="button secondary" data-repair-evidence="${esc(run?.id||'')}" ${!run?.repairResult||runtime.actionBusy?'disabled':''}>讀取修復與 trace</button><button class="button secondary" data-repair-patch ${!evidence?'disabled':''}>下載 patch</button></div>
 ${runtime.repairEvidenceError?`<div class="error-banner">${esc(runtime.repairEvidenceError)}</div>`:''}
 ${evidence?`<div class="diff"><div><div class="diff-heading">修復前</div><pre>${esc(evidence.baseline)}</pre></div><div><div class="diff-heading accent">修復後</div><pre>${esc(evidence.candidate)}</pre></div></div><div class="table-wrap"><table><thead><tr><th>工具</th><th>狀態</th><th>執行結果</th></tr></thead><tbody>${evidence.tools.map(t=>`<tr><td>#${t.id} · ${esc(t.name)}</td><td>${esc(t.status)}</td><td><pre class="log-message">${esc(t.error||t.result)}</pre></td></tr>`).join('')||'<tr><td colspan="3">模型未使用工具；可信測試仍會執行。</td></tr>'}</tbody></table></div>`:'<div class="empty">完成一輪後讀取候選檔與工具 trace。</div>'}
 <div class="small-notice">本階段產生修復檔與評測證據，不建立新 Skill 版本、不自動部署修復碼。完整 requests、SSE events、SDK 結果與測試保存於 .local/runs/；預覽超限時請在 WSL 檢閱原始檔案。</div></section>
 <section class="card spaced"><div class="card-heading"><h2>近期 Python 修復實驗</h2><button class="button secondary" data-repair-select="">查看最新</button></div><div class="table-wrap"><table><thead><tr><th>Run</th><th>狀態</th><th>建立時間</th></tr></thead><tbody>${(workspace?.runs||[]).map(r=>`<tr><td><button class="text-button" data-repair-select="${esc(r.id)}">${esc(r.id)}</button></td><td>${esc(LIVE_STATUSES[r.status])}</td><td>${esc(r.createdAt)}</td></tr>`).join('')||'<tr><td colspan="3">尚無紀錄</td></tr>'}</tbody></table></div></section>`;
}
